import{_ as t,l as o,o as a,c as i,v as l,p as n,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const M=JSON.parse('{"title":"用户态调度与 M:N","description":"","frontmatter":{"title":"用户态调度与 M:N","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/user-level-scheduling.md","filePath":"cs/user-level-scheduling.md","lastUpdated":1789023840000}'),h={name:"cs/user-level-scheduling.md"};function u(E,e,f,_,A,m){const s=o("Mermaid");return a(),i("div",null,[e[1]||(e[1]=l('<h1 id="用户态调度与-m-n" tabindex="-1">用户态调度与 M:N <a class="header-anchor" href="#用户态调度与-m-n" aria-label="Permalink to &quot;用户态调度与 M:N&quot;">​</a></h1><div class="epigraph"><p>M:N 把许多用户纤维映射到较少内核线程：切换可在用户完成，但阻塞系统调用会卡住整根内核线程，除非另做包装。</p><footer>—— 据 Anderson et al. 对调度器激活的论述；Go/Erlang 运行时实践；[线程](/cs/thread-shared-addr) 为先修</footer></div><p><a href="/cs/sched-ext">sched_ext</a> 仍决定内核任务。<a href="/cs/ult-klt">ULT/KLT</a> 主干有分类。缺口是 <strong>用户态 M:N 的 OS 接头</strong>：阻塞、信号、与 1:1 的取舍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>1:1：每个 goroutine 若都是内核线程，创建贵。M:N：用户调度器把可运行纤维放到 M 个 pthread 上。缺口：<code>read</code> 阻塞会占死一个 M；需要 netpoller 把 fd 变非阻塞 + 用户等待队列；与 <a href="/cs/napi">NAPI</a> 无关直接，但 eventfd/epoll 是接头。本课不把 Go GMP 细节背完。</p><p><span class="marginnote">scheduler activations 试图让内核通知用户「这根线程阻塞了」。Linux 上实践多是运行时自己包装 syscall。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>运行时：工作窃取队列，fiber 切换改上下文（不进核）。I/O：epoll + 非阻塞。对照 <a href="/cs/posix-aio">POSIX AIO</a>：一个内核完成，一个用户把阻塞变事件。对照 <a href="/cs/userfaultfd">uffd</a>：缺页仍进核。对照 EEVDF：内核只看见 N 个线程的 util。</p>',8)),(a(),n(p,null,{default:r(()=>[c(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E7%94%A8%E6%88%B7%E7%BA%A4%E7%BB%B4%22%5D%20--%3E%20U%5B%22%E7%94%A8%E6%88%B7%E8%B0%83%E5%BA%A6%E5%99%A8%22%5D%0A%20%20U%20--%3E%20M%5B%22%E5%86%85%E6%A0%B8%E7%BA%BF%E7%A8%8B%22%5D%0A%20%20BLK%5B%22%E9%98%BB%E5%A1%9E%20syscall%22%5D%20--%3E%20STUCK%5B%22%E8%AF%A5%20M%20%E5%8D%A1%E4%BD%8F%22%5D%0A%20%20IO%5B%22%E9%9D%9E%E9%98%BB%E5%A1%9E%2Bepoll%22%5D%20--%3E%20U%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>M:N 用用户切换换百万级并发，把 OS 调度粒度变粗。正确性取决于运行时包装了所有阻塞点。不要写成语言课的 async 语法。与 <a href="/cs/cgroup-cpu-sched">cgroup</a>：限额作用在 M 上，纤维数看不见。</p><p>信号与 TLS：要按纤维还是按 M 投递，是实现地狱，课序只要求意识到裂缝。</p><p>实现上：运行时必须包装所有可能阻塞的 libc，包括 getaddrinfo 和锁。信号投到 M 上，要转给当前纤维。cgroup 限额看见的是 M 的 CPU，不是纤维数。 读法上只引用<a href="/cs/sched-ext">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>用户态调度与 M:N</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 stackful vs stackless 的全部。不保证与 C 库的取消点。下一课更简单的一端：协作调度。</p><p>版本字段会变，课序钉的是机制对象「用户态调度与 M:N」，不是某一主线内核的结构体名。 后课默认：M:N 依赖非阻塞包装。自愿让出的协作式调度，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>M:N：用户调度纤维，内核只见少量线程。</li><li>阻塞 syscall 是主要裂缝。</li><li>协作调度是下一课。</li><li>出处：Anderson 调度器激活；Go 运行时；<em>OSTEP</em> 线程。</li></ul>',11))])}const T=t(h,[["render",u]]);export{M as __pageData,T as default};
